macro_rules! CompilerInterface {
    () => {
        deps!();
        # [doc = " Public API for querying compiler information."] # [doc = ""] # [doc = " All queries are delegated to [`rustc_public_bridge::context::CompilerCtxt`] that provides"] # [doc = " similar APIs but based on internal rustc constructs."] # [doc = ""] # [doc = " Do not use this directly. This is currently used in the macro expansion."] pub (crate) trait CompilerInterface { fn entry_fn (& self) -> Option < CrateItem > ; # [doc = " Retrieve all items of the local crate that have a MIR associated with them."] fn all_local_items (& self) -> CrateItems ; # [doc = " Retrieve the body of a function."] # [doc = " This function will panic if the body is not available."] fn mir_body (& self , item : DefId) -> mir :: Body ; # [doc = " Check whether the body of a function is available."] fn has_body (& self , item : DefId) -> bool ; fn foreign_modules (& self , crate_num : CrateNum) -> Vec < ForeignModuleDef > ; # [doc = " Retrieve all functions defined in this crate."] fn crate_functions (& self , crate_num : CrateNum) -> Vec < FnDef > ; # [doc = " Retrieve all static items defined in this crate."] fn crate_statics (& self , crate_num : CrateNum) -> Vec < StaticDef > ; fn foreign_module (& self , mod_def : ForeignModuleDef) -> ForeignModule ; fn foreign_items (& self , mod_def : ForeignModuleDef) -> Vec < ForeignDef > ; fn all_trait_decls (& self) -> TraitDecls ; fn trait_decls (& self , crate_num : CrateNum) -> TraitDecls ; fn trait_decl (& self , trait_def : & TraitDef) -> TraitDecl ; fn all_trait_impls (& self) -> ImplTraitDecls ; fn trait_impls (& self , crate_num : CrateNum) -> ImplTraitDecls ; fn trait_impl (& self , trait_impl : & ImplDef) -> ImplTrait ; fn generics_of (& self , def_id : DefId) -> Generics ; fn predicates_of (& self , def_id : DefId) -> GenericPredicates ; fn explicit_predicates_of (& self , def_id : DefId) -> GenericPredicates ; # [doc = " Get information about the local crate."] fn local_crate (& self) -> Crate ; # [doc = " Retrieve a list of all external crates."] fn external_crates (& self) -> Vec < Crate > ; # [doc = " Find a crate with the given name."] fn find_crates (& self , name : & str) -> Vec < Crate > ; # [doc = " Returns the name of given `DefId`"] fn def_name (& self , def_id : DefId , trimmed : bool) -> Symbol ; # [doc = " Return registered tool attributes with the given attribute name."] # [doc = ""] # [doc = " FIXME(jdonszelmann): may panic on non-tool attributes. After more attribute work, non-tool"] # [doc = " attributes will simply return an empty list."] # [doc = ""] # [doc = " Single segmented name like `#[clippy]` is specified as `&[\"clippy\".to_string()]`."] # [doc = " Multi-segmented name like `#[rustfmt::skip]` is specified as `&[\"rustfmt\".to_string(), \"skip\".to_string()]`."] fn tool_attrs (& self , def_id : DefId , attr : & [Symbol]) -> Vec < Attribute > ; # [doc = " Get all tool attributes of a definition."] fn all_tool_attrs (& self , def_id : DefId) -> Vec < Attribute > ; # [doc = " Returns printable, human readable form of `Span`"] fn span_to_string (& self , span : Span) -> String ; # [doc = " Return filename from given `Span`, for diagnostic purposes"] fn get_filename (& self , span : & Span) -> Filename ; # [doc = " Return lines corresponding to this `Span`"] fn get_lines (& self , span : & Span) -> LineInfo ; # [doc = " Returns the `kind` of given `DefId`"] fn item_kind (& self , item : CrateItem) -> ItemKind ; # [doc = " Returns whether this is a foreign item."] fn is_foreign_item (& self , item : DefId) -> bool ; # [doc = " Returns the kind of a given foreign item."] fn foreign_item_kind (& self , def : ForeignDef) -> ForeignItemKind ; # [doc = " Returns the kind of a given algebraic data type"] fn adt_kind (& self , def : AdtDef) -> AdtKind ; # [doc = " Returns if the ADT is a box."] fn adt_is_box (& self , def : AdtDef) -> bool ; # [doc = " Returns whether this ADT is simd."] fn adt_is_simd (& self , def : AdtDef) -> bool ; # [doc = " Returns whether this definition is a C string."] fn adt_is_cstr (& self , def : AdtDef) -> bool ; # [doc = " Returns the representation options for this ADT."] fn adt_repr (& self , def : AdtDef) -> ReprOptions ; # [doc = " Retrieve the function signature for the given generic arguments."] fn fn_sig (& self , def : FnDef , args : & GenericArgs) -> PolyFnSig ; # [doc = " Retrieve the intrinsic definition if the item corresponds one."] fn intrinsic (& self , item : DefId) -> Option < IntrinsicDef > ; # [doc = " Retrieve the plain function name of an intrinsic."] fn intrinsic_name (& self , def : IntrinsicDef) -> Symbol ; # [doc = " Retrieve the closure signature for the given generic arguments."] fn closure_sig (& self , args : & GenericArgs) -> PolyFnSig ; # [doc = " The number of variants in this ADT."] fn adt_variants_len (& self , def : AdtDef) -> usize ; # [doc = " Discriminant for a given variant index of AdtDef."] fn adt_discr_for_variant (& self , adt : AdtDef , variant : VariantIdx) -> Discr ; # [doc = " Discriminant for a given variand index and args of a coroutine."] fn coroutine_discr_for_variant (& self , coroutine : CoroutineDef , args : & GenericArgs , variant : VariantIdx ,) -> Discr ; # [doc = " The name of a variant."] fn variant_name (& self , def : VariantDef) -> Symbol ; fn variant_fields (& self , def : VariantDef) -> Vec < FieldDef > ; # [doc = " Evaluate constant as a target usize."] fn eval_target_usize (& self , cnst : & MirConst) -> Result < u64 , Error > ; fn eval_target_usize_ty (& self , cnst : & TyConst) -> Result < u64 , Error > ; # [doc = " Create a new zero-sized constant."] fn try_new_const_zst (& self , ty : Ty) -> Result < MirConst , Error > ; # [doc = " Create a new constant that represents the given string value."] fn new_const_str (& self , value : & str) -> MirConst ; # [doc = " Create a new constant that represents the given boolean value."] fn new_const_bool (& self , value : bool) -> MirConst ; # [doc = " Create a new constant that represents the given value."] fn try_new_const_uint (& self , value : u128 , uint_ty : UintTy) -> Result < MirConst , Error > ; fn try_new_ty_const_uint (& self , value : u128 , uint_ty : UintTy) -> Result < TyConst , Error > ; # [doc = " Create a new type from the given kind."] fn new_rigid_ty (& self , kind : RigidTy) -> Ty ; # [doc = " Create a new box type, `Box<T>`, for the given inner type `T`."] fn new_box_ty (& self , ty : Ty) -> Ty ; # [doc = " Returns the type of given crate item."] fn def_ty (& self , item : DefId) -> Ty ; # [doc = " Returns the type of given definition instantiated with the given arguments."] fn def_ty_with_args (& self , item : DefId , args : & GenericArgs) -> Ty ; # [doc = " Returns literal value of a const as a string."] fn mir_const_pretty (& self , cnst : & MirConst) -> String ; # [doc = " `Span` of an item"] fn span_of_an_item (& self , def_id : DefId) -> Span ; fn ty_const_pretty (& self , ct : TyConstId) -> String ; # [doc = " Obtain the representation of a type."] fn ty_pretty (& self , ty : Ty) -> String ; # [doc = " Obtain the kind of a type."] fn ty_kind (& self , ty : Ty) -> TyKind ; fn rigid_ty_discriminant_ty (& self , ty : & RigidTy) -> Ty ; # [doc = " Get the body of an Instance which is already monomorphized."] fn instance_body (& self , instance : InstanceDef) -> Option < Body > ; # [doc = " Get the instance type with generic instantiations applied and lifetimes erased."] fn instance_ty (& self , instance : InstanceDef) -> Ty ; # [doc = " Get the instantiation types."] fn instance_args (& self , def : InstanceDef) -> GenericArgs ; # [doc = " Get the instance."] fn instance_def_id (& self , instance : InstanceDef) -> DefId ; # [doc = " Get the instance mangled name."] fn instance_mangled_name (& self , instance : InstanceDef) -> Symbol ; # [doc = " Check if this is an empty DropGlue shim."] fn is_empty_drop_shim (& self , def : InstanceDef) -> bool ; # [doc = " Convert a non-generic crate item into an instance."] # [doc = " This function will panic if the item is generic."] fn mono_instance (& self , def_id : DefId) -> Instance ; # [doc = " Item requires monomorphization."] fn requires_monomorphization (& self , def_id : DefId) -> bool ; # [doc = " Resolve an instance from the given function definition and generic arguments."] fn resolve_instance (& self , def : FnDef , args : & GenericArgs) -> Option < Instance > ; # [doc = " Resolve an instance for drop_in_place for the given type."] fn resolve_drop_in_place (& self , ty : Ty) -> Instance ; # [doc = " Resolve instance for a function pointer."] fn resolve_for_fn_ptr (& self , def : FnDef , args : & GenericArgs) -> Option < Instance > ; # [doc = " Resolve instance for a closure with the requested type."] fn resolve_closure (& self , def : ClosureDef , args : & GenericArgs , kind : ClosureKind ,) -> Option < Instance > ; # [doc = " Evaluate a static's initializer."] fn eval_static_initializer (& self , def : StaticDef) -> Result < Allocation , Error > ; # [doc = " Try to evaluate an instance into a constant."] fn eval_instance (& self , def : InstanceDef , const_ty : Ty) -> Result < Allocation , Error > ; # [doc = " Retrieve global allocation for the given allocation ID."] fn global_alloc (& self , id : AllocId) -> GlobalAlloc ; # [doc = " Retrieve the id for the virtual table."] fn vtable_allocation (& self , global_alloc : & GlobalAlloc) -> Option < AllocId > ; fn krate (& self , def_id : DefId) -> Crate ; fn instance_name (& self , def : InstanceDef , trimmed : bool) -> Symbol ; # [doc = " Return information about the target machine."] fn target_info (& self) -> MachineInfo ; # [doc = " Get an instance ABI."] fn instance_abi (& self , def : InstanceDef) -> Result < FnAbi , Error > ; # [doc = " Get the ABI of a function pointer."] fn fn_ptr_abi (& self , fn_ptr : PolyFnSig) -> Result < FnAbi , Error > ; # [doc = " Get the layout of a type."] fn ty_layout (& self , ty : Ty) -> Result < Layout , Error > ; # [doc = " Get the layout shape."] fn layout_shape (& self , id : Layout) -> LayoutShape ; # [doc = " Get a debug string representation of a place."] fn place_pretty (& self , place : & Place) -> String ; # [doc = " Get the resulting type of binary operation."] fn binop_ty (& self , bin_op : BinOp , rhs : Ty , lhs : Ty) -> Ty ; # [doc = " Get the resulting type of unary operation."] fn unop_ty (& self , un_op : UnOp , arg : Ty) -> Ty ; # [doc = " Get all associated items of a definition."] fn associated_items (& self , def_id : DefId) -> AssocItems ; }
    };
}

CompilerInterface!()